class LmdbBackupRawEpochTest {

	@Test
	void flatRawBytesDoNotAddAnEpochReservation(@TempDir Path directory) throws Exception {
		Statement statement = statement();
		ValueStore values = new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
		try {
			values.startTransaction(false);
			long[] quad = store(values, statement);
			values.commit();
			// A pre-existing reader demonstrates why this contract is a delta, rather than an absolute zero.
			try (ValueStore.ReadSnapshotReservation reservation = values.reserveReadSnapshot();
					ValueStore.ReadSnapshot snapshot = reservation.start()) {
				values.startTransaction(false);
				try {
					AtomicLong firstByteReservations = new AtomicLong(-1L);
					ByteArrayOutputStream encoded = new ByteArrayOutputStream();
					DataOutputStream observed = new DataOutputStream(new OutputStream() {
						private void observe() {
							firstByteReservations.compareAndSet(-1L,
									values.protectionSnapshotForTest().readerReservations());
						}

						@Override
						public void write(int value) {
							observe();
							encoded.write(value);
						}

						@Override
						public void write(byte[] bytes, int offset, int length) {
							if (length > 0) {
								observe();
							}
							encoded.write(bytes, offset, length);
						}
					});
					long before = values.protectionSnapshotForTest().readerReservations();
					assertTrue(values.writeBackupRecord(observed, false, true, quad, new byte[64]));
					assertTrue(firstByteReservations.get() >= 0, "The test must observe actual native record output");
					ByteArrayOutputStream expected = new ByteArrayOutputStream();
					LmdbBackupDeltaCodec.writeRecord(new DataOutputStream(expected),
							new Record(false, true, statement));
					assertArrayEquals(expected.toByteArray(), encoded.toByteArray());
					assertEquals(before, values.protectionSnapshotForTest().readerReservations(),
							"Native capture must preserve the caller's existing reservation count");
					System.out.printf("BACKUP_RAW_RESERVATIONS,before=%d,first_byte=%d,delta=%d%n", before,
							firstByteReservations.get(), firstByteReservations.get() - before);
					assertEquals(0L, firstByteReservations.get() - before,
							"Already admitted flat raw capture must not add a model epoch reservation");
				} finally {
					values.rollback();
				}
			}
		} finally {
			close(values);
		}
	}

	@Test
	void rawCaptureFailureRestoresNestedStackAndLeavesWriterUsable(@TempDir Path directory) throws Exception {
		Statement statement = statement();
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		LmdbBackupDeltaCodec.writeRecord(new DataOutputStream(expected), new Record(false, true, statement));
		byte[] expectedBytes = expected.toByteArray();
		ValueStore values = new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
		try {
			values.startTransaction(false);
			long[] quad = store(values, statement);
			long reservations = values.protectionSnapshotForTest().readerReservations();
			try (MemoryStack stack = MemoryStack.stackPush()) {
				ByteBuffer sentinel = stack.malloc(2 * Long.BYTES);
				sentinel.putLong(0, 0x13579bdf2468ace0L);
				sentinel.putLong(Long.BYTES, 0x02468ace13579bdfL);
				int pointer = stack.getPointer();
				ByteArrayOutputStream prefix = new ByteArrayOutputStream();
				IOException failure = new IOException("Injected failure after native dictionary bytes");
				DataOutputStream failing = new DataOutputStream(new OutputStream() {
					private void failAfterNativeBytes() throws IOException {
						// The opcode, explicit flag, IRI tag and length precede the mapped UTF-8 payload.
						if (prefix.size() > 3 + Integer.BYTES) {
							throw failure;
						}
					}

					@Override
					public void write(int value) throws IOException {
						prefix.write(value);
						failAfterNativeBytes();
					}

					@Override
					public void write(byte[] bytes, int offset, int length) throws IOException {
						prefix.write(bytes, offset, length);
						failAfterNativeBytes();
					}
				});
				assertSame(failure, assertThrows(IOException.class,
						() -> values.writeBackupRecord(failing, false, true, quad, new byte[64])));
				assertTrue(prefix.size() > 3 + Integer.BYTES,
						"The failure must follow actual dictionary UTF-8 output");
				assertTrue(prefix.size() < expectedBytes.length, "The first capture must stop within its record");
				assertArrayEquals(Arrays.copyOf(expectedBytes, prefix.size()), prefix.toByteArray());
				assertEquals(pointer, stack.getPointer(), "Failed capture must restore the caller's stack frame");
				assertEquals(0x13579bdf2468ace0L, sentinel.getLong(0));
				assertEquals(0x02468ace13579bdfL, sentinel.getLong(Long.BYTES));
				assertEquals(reservations, values.protectionSnapshotForTest().readerReservations());

				ByteArrayOutputStream retry = new ByteArrayOutputStream();
				assertTrue(values.writeBackupRecord(new DataOutputStream(retry), false, true, quad, new byte[64]));
				assertArrayEquals(expectedBytes, retry.toByteArray());
				assertEquals(pointer, stack.getPointer(), "Successful capture must restore the caller's stack frame");
				assertEquals(0x13579bdf2468ace0L, sentinel.getLong(0));
				assertEquals(0x02468ace13579bdfL, sentinel.getLong(Long.BYTES));
			}
			values.commit();
			assertEquals(quad[0], values.getId(statement.getSubject()),
					"The dictionary writer must remain usable through normal commit");
			assertEquals(reservations, values.protectionSnapshotForTest().readerReservations());
		} finally {
			close(values);
		}
	}

	/**
	 * New guarded postcondition. Its pre-change execution is deliberately excluded: the old encoder can pass a zero
	 * transaction handle to native code when called outside an admitted writer.
	 */
	@Test
	void rawCaptureWithoutNativeWriterReturnsFalseBeforeOutput(@TempDir Path directory) throws Exception {
		ValueStore values = new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
		try {
			values.startTransaction(false);
			long[] quad = store(values, statement());
			values.commit();
			long before = values.protectionSnapshotForTest().readerReservations();
			ByteArrayOutputStream encoded = new ByteArrayOutputStream();
			assertFalse(values.writeBackupRecord(new DataOutputStream(encoded), false, true, quad, new byte[64]),
					"Without a live admitted writer, native capture must request protected model fallback");
			assertEquals(0, encoded.size(), "The unavailable fast path must write no partial record");
			assertEquals(before, values.protectionSnapshotForTest().readerReservations());
		} finally {
			close(values);
		}
	}

	private static Statement statement() {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("https://epoch.example/subject"),
				values.createIRI("https://epoch.example/predicate"),
				values.createLiteral("owned raw literal-𝄞", values.createIRI("https://datatype.example/type")),
				values.createIRI("https://epoch.example/context"));
	}

	private static long[] store(ValueStore values, Statement statement) throws IOException {
		return new long[] { values.storeValue(statement.getSubject()), values.storeValue(statement.getPredicate()),
				values.storeValue(statement.getObject()), values.storeValue(statement.getContext()) };
	}

	private static void close(ValueStore values) throws IOException {
		try {
			values.rollback();
		} finally {
			values.close();
		}
	}
}
